INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (1, 'room-acoustic-performance', NULL, 'EN', 1, 'co1', 'intrinsic', 'autistic adults lived experience of noise and reverberation in buildings, qualitative interview and participatory design studies', NULL, 'consensus', 'scoping', NULL, 20, 10, 2, NULL, '["REF-00965", "REF-00966"]', NULL, 0, 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19 13:28', NULL, 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (2, 'room-acoustic-performance', NULL, 'EN', 1, 'co1', 'intrinsic', 'lived experience of people with dementia and their perspectives on noise and sound environment in care settings, qualitative and co-design studies', NULL, 'consensus', 'scoping', NULL, 20, 10, 0, NULL, NULL, NULL, 0, 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19 13:29', 'Co-1 yield is real but OFF-PARAMETER: the DEM lived-experience literature centres soundscape, meaning and social use of sound, not room-acoustic performance (reverberation, absorption). Sound-as-resource, not sound-as-hazard. Recorded so a later reader does not mistake a rich Co-1 seam for evidence about the parameter.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (3, 'room-acoustic-performance', NULL, 'EN', 2, 'sr_meta', 'high_control', 'systematic review of reverberation time and speech perception outcomes for listeners with hearing impairment or cognitive impairment in rooms', NULL, 'consensus', 'systematic', NULL, 20, 10, 1, NULL, '["REF-00607"]', NULL, 0, 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19 13:30', 'On-parameter T2 seam exists. R13 flag recorded at search time, before screening: the strongest hit studies predominantly NORMAL-HEARING listeners, so it is PROXY at best for every population this slug serves. Population-of-study is not population-served.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (4, 'room-acoustic-performance', 'DE', 'DE', 5, 'national_fw', 'national', 'DIN 18041 Hörsamkeit in Räumen Nachhallzeit Anforderungen barrierefrei Raumgruppe', NULL, 'web', 'scoping', NULL, 7, 7, 0, NULL, NULL, NULL, 0, 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19 13:30', '[UNVERIFIED-QUANT] DIN 18041:2016 located as a real national framework, and the 2016 revision is reported to have been prompted by accessibility/inclusion requirements — which is directly on-topic. But every numeric value reaching me came from SECONDARY commentary, not the standard text: I have not held a clause. Under R3 no value from this search may be recorded as a determination until the clause is retrieved. Logged as a located, unquantified lead.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (5, 'room-acoustic-performance', NULL, 'EN', 1, 'clinical', 'high_control', 'controlled experiment reverberation time speech recognition older adults with cognitive impairment or hearing loss in rooms', NULL, 'consensus', 'systematic', NULL, 20, 10, 0, NULL, NULL, NULL, 0, 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19 13:31', 'NEAR-ZERO YIELD ON PARAMETER (R14): 20 results on-topic to the query, off-topic to the parameter — almost entirely auditory-training and cochlear-implant trials. The controlled evidence base remediates the LISTENER, not the ROOM. That asymmetry is the finding.', 1);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (6, 'room-acoustic-performance', NULL, 'EN', 1, 'clinical', 'intrinsic', 'unpredictable intermittent sound and sensory load effects on attention and perceptual function for neurodivergent and brain-injured adults in indoor environments', NULL, 'consensus', 'scoping', NULL, 20, 10, 2, NULL, '["REF-00967", "REF-00968"]', NULL, 0, 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19 13:33', 'AX-SPR seam (ICF b156 perceptual / b140 attention), opened only after the owner corrected the frame pull to ICF codes WITH NAMES. Materially different literature from the four preceding AX-AUD searches (b230/d310): controlled indoor-environment work on neurodivergent adults, plus an IPA study whose themes are Acoustical Control as Cognitive Safety and Restoration is Not Silence — imposed silence experienced as taxing, predictability and personal control ranking above level. This CONTRADICTS a level-reduction determination and is why the axis had to be searched on its own mechanism. Method finding: 4 of the first 5 searches were framed on one axis because the frame was pulled as bare axis_codes; the ICF anchors are what made the second mechanism visible.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (7, 'room-acoustic-performance', NULL, 'EN', 2, 'sr_meta', NULL, 'Crossref reference-list retrieval for REF-00607 and REF-00965 (backward citation chase, depth 1)', NULL, 'crossref', 'scoping', 'backward', 145, 0, 0, NULL, NULL, NULL, 0, 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19', 'Depth-1 backward chase over two anchors: 145 DOI-bearing references recovered (81 + 64). Screened 0 this pass and that is deliberate, not an omission - screening them is batch 2 work under R2 depth 2-3, and staging 145 candidates would blow the minimum-viable scope this batch was held to. Logged so the chase is auditable and so batch 2 does not re-run it.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (8, 'room-acoustic-performance', NULL, 'EN', 1, 'co1', 'intrinsic', 'lived experience of spinal cord injury wheelchair users regarding room reverberation time and acoustic absorption in buildings', NULL, 'consensus', 'scoping', 'none', 20, 20, 0, NULL, NULL, NULL, 0, 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19', 'ZERO YIELD ON THE TARGETED CELL, recorded as found=20 rather than found=0 because that is what happened: the engine returned 20 rows and NONE addressed the intersection. It returned the two literatures SEPARATELY - room-acoustics studies with no SCI participants, and SCI studies (standing wheelchairs, dysphonia) with no room-acoustic content. R14 diagnosis: not query-shape failure, the query was well formed and both halves were clearly parsed; not wrong index, Consensus covers both bodies; GENUINE ABSENCE of the intersection. SCI carries 1 item on this slug and has no lived-experience evidence base for this parameter. Flagged as an inadequacy finding under R7.', 1);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (9, 'room-acoustic-performance', NULL, 'EN', 1, 'co1', NULL, '[NOT RUN] AX-PAI pain-load demand x room acoustic performance', NULL, 'manual', 'scoping', 'none', 0, 0, 0, NULL, NULL, 'DELIBERATELY NOT SEARCHED this batch. AX-PAI (ICF b280, sensation of pain) carries 2 of the 13 items on this slug, and its axis mechanism is impact, vibration, pressure and cold - a structure-borne and tactile demand, not an airborne room-acoustic one. Searching it under this slug would have imported the wrong mechanism. It needs its own frame and belongs with a vibration/structure-borne slug. Recorded as a reasoned deferral, not a gap in coverage.', 0, 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19', NULL, 0);
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (1, 'REF-00965', '2026-08-19', 'session_2026-08-19-research-batch-01-room-acoustic-performance');
