INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (6, 'REF-00968', '2026-08-19', 'session_2026-08-19-research-batch-01-room-acoustic-performance');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (1, 6, 'room-acoustic-performance', NULL, 'ADMITTED', 'Listening beyond the noise: IPA of mental fatigue and restoration in neurodivergent students acoustical environments', '10.1080/23311886.2026.2645738', 'RESOLVED', 1, 0, NULL, 'RESOLVED: re-described from the source record. STAGED HYPOTHESIS was ''evidence that neurodivergent students need lower noise levels''. Wrong, and corrected here: the themes are Acoustical Control as Cognitive Safety and Restoration is Not Silence - imposed silence was experienced as emotionally taxing, and predictability plus personal control ranked above level. Admitted as REF-00968. The hypothesis would have inverted the requirement class.', 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (2, 1, 'room-acoustic-performance', NULL, 'REHOME', 'Experiences of Sensory Overload and Communication Barriers by Autistic Adults in Health Care Settings', '10.1089/aut.2020.0074', 'RESOLVED', 1, 1, 'Off-slug: healthcare-setting sensory environment, not room acoustic performance as a parameter.', 'Real Co-1 material carrying a harm finding (avoidance of care). Belongs to a healthcare-environment slug. Rehomed rather than admitted here so it is not lost.', 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (3, 3, 'room-acoustic-performance', NULL, 'REHOME', 'Indoor soundscape, speech perception and cognition in classrooms: systematic review of ventilation-related sounds', '10.1016/j.buildenv.2023.110194', 'UNVERIFIED', 2, 0, 'Off-parameter: subject is ventilation-source noise, not room acoustic response.', 'T2 systematic review adjacent to this slug. Locator NOT re-retrieved, so staged UNVERIFIED and not admissible until R10 is run on it.', 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19');
