INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('room-acoustic-performance', 'RAP-01', 'REF-00965', '10.1016/j.apacoust.2025.110581', 1, 0, '[]', 'Backward mining run via Crossref: 108 references listed, 64 carrying a DOI. The reference list is the richest Co-1 seam found this batch - it reaches the sound-tolerance and hyperacusis literature (decreased sound tolerance prevalence, qualitative noise-sensitivity studies) that none of my six queries surfaced directly. Recorded as the highest-value lead set for batch 2.', '2026-08-19', 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19', 'session_2026-08-19-research-batch-01-room-acoustic-performance', NULL);
INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('room-acoustic-performance', 'RAP-04', 'REF-00607', '10.1177/23312165241273399', 1, 0, '[]', 'Backward mining run via Crossref: 93 references listed, 81 carrying a DOI. Forward not run this pass (cited-by = 7, low yield). NOT harvested into source_locators: the section 6 widening is OD-5 and still open, so the 81 identifiers stay in this note rather than being written to a store whose promotion columns do not exist yet. This is a deliberate deferral, not an omission.', '2026-08-19', 'session_2026-08-19-research-batch-01-room-acoustic-performance', '2026-08-19', 'session_2026-08-19-research-batch-01-room-acoustic-performance', NULL);